package com.giftplatform.hostpayment.verification;import java.util.Objects;import java.util.UUID;/** Pure read-only correlation + interpretation; NEVER changes attempts or payout destinations. */public final class RazorpayXReconciliationPreview { @FunctionalInterface public interface AuthenticatedLookup {  String fetch(String requestReference) throws Exception; } private static RazorpayXValidationResponse parse(String json) throws Exception {  var root=new tools.jackson.databind.ObjectMapper().readTree(json);  return new RazorpayXValidationResponse(   value(root,"id"),value(root,"entity"),value(root,"status"),   value(root.path("results"),"account_status"),   value(root.path("results"),"registered_name"),   value(root.path("fund_account"),"id"),   value(root.path("fund_account"),"account_type")); } private static String value(tools.jackson.databind.JsonNode node,String key){  var child=node.path(key);return child.isMissingNode()||child.isNull()?null:child.asText(); } private final AuthenticatedLookup lookup; public RazorpayXReconciliationPreview(AuthenticatedLookup lookup){this.lookup=Objects.requireNonNull(lookup);} public VerificationOutcome preview(VerificationAttempt attempt,UUID hostId,UUID destinationId,                                    String expectedHolderName) {  if(attempt==null||hostId==null||destinationId==null||expectedHolderName==null||expectedHolderName.isBlank())   throw new IllegalArgumentException("Complete request context required");  if(!hostId.equals(attempt.getHostId())||!destinationId.equals(attempt.getDestinationId()))   throw new IllegalArgumentException("Attempt ownership mismatch");  if(attempt.getDestinationKind()!=HostDestinationVerifier.Kind.BANK)   throw new IllegalArgumentException("Bank validation only");  VerificationResultMatcher.requirePending(attempt.getState());  VerificationRequestBinding binding=attempt.getRequestBinding();  if(binding==null||!"RAZORPAYX".equals(binding.provider()))   throw new IllegalStateException("Missing trusted RazorpayX request binding");  try {   String json=lookup.fetch(binding.requestReference());   if(json==null||json.isBlank())return VerificationOutcome.UNAVAILABLE;   RazorpayXValidationResponse response=parse(json);   if(!binding.requestReference().equals(response.id()))return VerificationOutcome.UNAVAILABLE;   return new RazorpayXValidationInterpreter().interpretBank(response,binding.fundAccountId(),expectedHolderName).outcome();  } catch(Exception e) {   /* Never log response bodies, credentials, account numbers, or holder names. */   return VerificationOutcome.UNAVAILABLE;  } }}
